import httpRequest from "@/apis/axios-api";

import type { Announcement, BannerItem, FriendLink, Notification } from "@/types/system.ts";

/** 首页聚合数据的单模块返回结构（各字段均为可选，`code` 为 0 表示成功） */
export interface HomeCodeResult<T> {
  code?: number;
  data?: T;
}

/** 评测统计单日数据（`/judge/statics/recently`） */
export interface HomeJudgeStaticsItem {
  date: string; // 统计日期
  accept: number; // 通过数
  attempt: number; // 提交数（含通过）
}

/** 签到统计单日数据（`/checkin/statics/recently`） */
export interface HomeCheckinStaticsItem {
  date: string; // 统计日期
  count: number; // 签到人数
}

/** 每日一题单条记录（`/problem/daily/recently`） */
export interface HomeProblemDailyItem {
  key: string; // 每日一题记录标识
  title: string; // 题目标题
  problem_id: string; // 题目ID（用于取答题状态）
  problem_key: string; // 题目标识（用于跳转）
}

/** 首页聚合数据响应类型 */
export interface HomeAggregatedData {
  notification?: { code: number; data: Notification };
  announcement?: { code: number; data: Announcement };
  banners?: { code: number; data: { images: BannerItem[] } };
  judge_status?: { code: number; data: Array<{ name: string; url: string; status: string }> };
  friend_link?: { code: number; data: FriendLink[] };
  judge_statics?: HomeCodeResult<{ list: HomeJudgeStaticsItem[] }>;
  checkin_statics?: HomeCodeResult<{ list: HomeCheckinStaticsItem[] }>;
  // `attempt_status` 只会在登录用户单独请求时出现，聚合缓存里没有该字段
  daily?: HomeCodeResult<{
    time: string;
    list: HomeProblemDailyItem[];
    attempt_status?: Record<string, number>;
  }>;
}

/** 获取首页聚合数据（包含通知、公告、轮播图、评测机状态、友链、统计数据、每日题目） */
export function GetHomeData(): Promise<{ code: number; data: HomeAggregatedData }> {
  return httpRequest({
    url: "/home/data",
    method: "get",
  });
}
