import httpRequest from "@/apis/axios-api";

export enum TaskType {
  Unknown = 0,
  Problem = 1,
}

export enum TaskStatus {
  Pending = 0,
  Completed = 1,
  Claimed = 2,
}

export interface UserDailyTask {
  id: number;
  task_type: TaskType;
  task_index: number;
  target_id?: number;
  problem_key?: string;
  problem_title?: string;
  exp_reward: number;
  coin_reward: number;
  status: TaskStatus;
  insert_time: string;
}

export interface DailyTaskHomeResult {
  business_date: string;
  tasks?: UserDailyTask[];
  seconds_until_next: number;
}

export function GetDailyTaskHome() {
  return httpRequest({
    url: "/daily-task/home",
    method: "get",
  });
}

export function GetDailyTaskStatus() {
  return httpRequest({
    url: "/daily-task/status",
    method: "get",
  });
}

export function PostDailyTaskClaim(taskId: number) {
  return httpRequest({
    url: "/daily-task/claim",
    method: "post",
    params: { id: taskId },
  });
}
